class ta_enb_inner(object):
    """
    Class provides keywords for:
    """

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self.emil_trace_process = None
        self._ute_fsmaccess_instance = ute_fsmaccess()
        self.xml_instance = XML(use_lxml=True)
        self._ta5g_scfc_analysis_instance = ta5g_scfc_analysis()
        self._ta5g_testline_mgmt = ta5g_testline_management.ta5g_testline_management()
        self._enb_release = None
        self._fsm_type = None

    @contextmanager
    def _ute_fsm_configurator(self, alias=None, remote_host=None, host=ENB0_LMP_IP):
        """
        :param alias
        :param remote_host
        """
        alias = 'default' if not alias else alias
        try:
            self._ute_fsmaccess_instance.setup_enb_fsm_access(host=host, remote_host=remote_host, alias=alias)
            yield self._ute_fsmaccess_instance
        finally:
            self._ute_fsmaccess_instance.teardown_enb_fsm_access(alias=alias)

    @log_method_name
    def enable_enb_ssh_access(self, alias='default', remote_host=None):
        """Enables ssh access on enb"""
        with self._ute_fsm_configurator(remote_host=remote_host, alias=alias) as fsm_instance:
            fsm_instance.enable_enb_ssh(alias=alias)

    @log_method_name
    def execute_enb_command(self, cmd, remote_host=None, return_rc=False):
        """Executes command on enb and returns output"""
        with self._ute_fsm_configurator(remote_host=remote_host, alias='default') as fsm_instance:
            output = fsm_instance.execute_command_on_enb(cmd, alias='default', return_rc=return_rc)
        return output

