    @log_method_name
    def get_file_from_enb(self, source, destination, remote_host=None):
        """Gets file source from enb and saves it at destination"""
        with self._ute_fsm_configurator(remote_host=remote_host, alias='default') as fsm_instance:
            output = fsm_instance.get_enb_file(source, destination, alias='default')
        return output

    @log_method_name
    def multi_enb_backup_and_modify_swconfig_file(self, remote_host_list, parameters_list, output_dirpath=None):
        """
        :param remote_host_list: str
        :param parameters_list: list
        :param output_dirpath
        """
        if not output_dirpath:
            output_dirpath = get_robot_output_dir()
        env_count = len(remote_host_list)
        for env_id in range(0, env_count):
            self.backup_and_modify_swconfig_file(
                parameters_list=parameters_list,
                output_dirpath=output_dirpath + '/{}'.format(env_id),
                remote_host=remote_host_list[env_id],
            )

    @log_method_name
    def backup_and_modify_swconfig_file(self, parameters_list, output_dirpath=None, remote_host=None):
        """
        :param parameters_list: list
        :param output_dirpath: str
        :param remote_host
        """
        if not output_dirpath:
            output_dirpath = get_robot_output_dir()

        output_filepath = ta5g_file_system.join_path_with_timestamp_suffix(
            output_dirpath + '/{}'.format(ENB_SUBDIR), 'swconfig.txt'
        )
        self.get_swconfig_file(output_filepath=output_filepath, remote_host=remote_host)
        ta5g_file_system.duplicate_file_with_added_suffix(input_filepath=output_filepath, suffix='original')
        if parameters_list is None:
            return
        ta5g_dev_wro1().change_swconfig_params(output_filepath, *parameters_list)
        self.put_swconfig_file(output_filepath, remote_host=remote_host)

    @log_method_name
    def put_original_swconfig_file_on_enb(self):
        """
        Send original swconfig to enb
        """
        swconfig_backup = check_output(
            ["find {} -name '*original.txt' | sort -r | head -n 1".format(get_robot_output_dir())], shell=True
        )
        if swconfig_backup:
            if isinstance(swconfig_backup, str):
                self.put_swconfig_file(input_filepath=swconfig_backup.strip())
            else:
                swconfig = swconfig_backup.decode("utf-8")
                self.put_swconfig_file(input_filepath=swconfig.strip())

