    @log_method_name
    def get_bts_snapshot(self, output_filepath, remote_host='127.0.0.1', timeout=2400, coverage="Full", force=True):
        """
        :param force:
        :param coverage:
        :param timeout:
        :param output_filepath
        :param remote_host
        """

        if remote_host != '127.0.0.1':
            with ta_admin_interface.remote_admin_interface(remote_host=remote_host) as remote_admin_client:
                remote_admin_client.collect_snapshot(
                    target_file_name=output_filepath, coverage=coverage, force=force, timeout=timeout
                )
        else:
            with ta_admin_interface.admin_interface() as admin_client:
                admin_client.collect_snapshot(
                    target_file_name=output_filepath, coverage=coverage, force=force, timeout=timeout
                )

    @log_method_name
    def get_scfc_file(self, output_filepath, timeout=20, remote_host=None):
        """
        :param output_filepath
        :param timeout
        :param remote_host
        """
        suffix = '.xml' if '.xml' not in output_filepath else ''
        full_output_path = output_filepath + suffix
        local_dirpath, filename = os.path.split(full_output_path)
        with ta_admin_interface.get_admin_interface(remote_host=remote_host) as admin_client:
            admin_client.get_current_scf_file(local_dir_path=local_dirpath, file_name=filename, timeout=timeout)
        return output_filepath

    def get_scfc_file_aic(self, output_filepath):
        """
        Get scfc file aic vcu
        :param output_filepath
        """
        with ta5g_admin_operations().connect_to_vcu_aic() as vcu_connection:
            vcu_connection.get_current_plan_file(output_filepath)
        return output_filepath

    def get_scfc_file_vdu_aic(self, output_filepath, vdu=1):
        """
        Get scfc file aic vdu
        :param output_filepath
        :param vdu: by default set to 1, vdu from where scfc file should be get
        """
        tl = BuiltIn().get_variable_value("${tl}")
        vdu_master_ip = tl.gnbs[0].dus[int(vdu) - 1].oam_http_connection_details.addr
        output_dirpath, filename = os.path.split(output_filepath)
        with ta5g_admin_operations().connect_to_vdu_aic(host=vdu_master_ip) as vdu_connection:
            vdu_connection.get_current_plan_file(output_dirpath, filename)
        return output_filepath

