    @log_method_name  # noqa: C901
    def remove_file_checksum_and_hash_files(self, filename_prefix, fsm_type, logs_dirpath=None, remote_host=None):
        """Workaround for Fetaure LTE790 - simple crasign cmd does not work anymore
        This KW, for specified eNB file (filename_prefix), remove value of checksum in /rom/FileDirectory.xml and
        also hash container files
        Example: Remove File Checksum And Hash Files    filename_prefix=vendor
        :param filename_prefix
        :param fsm_type
        :param logs_dirpath
        :param remote_host
        """
        if not logs_dirpath:
            logs_dirpath = get_robot_output_dir()
        if int(fsm_type) <= 3:
            remove_cmd = 'rm /rom/HashContainer*.txt /rom/HashContainerSignature*.sig'
        else:
            remove_cmd = 'rm /ffs/run/HashContainer*'

        try:
            self.remove_checksum_from_file_directory(filename_prefix, logs_dirpath, remote_host)
        except Exception:
            pass
        try:
            self.execute_enb_command(
                cmd=remove_cmd, remote_host=remote_host
            )
        except Exception:
            pass

    @log_method_name
    def remove_checksum_from_file_directory(self, filename_prefix, logs_dirpath=None, remote_host=None):
        original_filedirectory_filepath = ta5g_file_system.join_path_with_timestamp_suffix(
            logs_dirpath, 'FileDirectory.xml'
        )
        self.get_filedirectory_file(output_filepath=original_filedirectory_filepath, remote_host=remote_host)
        modified_filedirectory_xml = self.xml_instance.set_element_attribute(
            source=original_filedirectory_filepath,
            name='checksum',
            value='',
            xpath='fileElement[@name = "' + filename_prefix + '"]',
        )
        modified_filedirectory_filepath = ta5g_file_system.join_path_with_timestamp_suffix(
            logs_dirpath, 'FileDirectory_MOD.xml'
        )
        self.xml_instance.save_xml(source=modified_filedirectory_xml, path=modified_filedirectory_filepath)
        self.put_filedirectory_file(input_filepath=modified_filedirectory_filepath, remote_host=remote_host)
        self.execute_enb_command(cmd='crasign /rom/FileDirectory.xml', remote_host=remote_host)

    @log_method_name
    def generate_scfc_file_from_enb_and_verify_value_from_scf(self, value, parameter_name, dist_name):
        """
        :param value
        :param parameter_name
        :param dist_name
        """
        output_filepath = self._ta5g_scfc_analysis_instance.get_latest_scfc(
            output_filename='scfc_' + get_robot_test_name() + '.xml', host_ip=None
        )
        scf_parameter = self.get_value_from_scf(
            parameter_name=parameter_name, dist_name=dist_name, scfc_filepath=output_filepath
        )
        if scf_parameter == value:
            return True
        raise AssertionError("SCF parameter: {} has value {} != {}".format(parameter_name, scf_parameter, value))

    @log_method_name
    def verify_value_from_scf(self, pass_criteria, parameter_name, dist_name, scfc_filepath):
        """
        :param pass_criteria
        :param parameter_name
        :param dist_name
        :param scfc_filepath
        """
        scf_parameter = self.get_value_from_scf(
            parameter_name=parameter_name, dist_name=dist_name, scfc_filepath=scfc_filepath
        )
        value_scf = convert_parameter_to_integer(scf_parameter)
        logger.info('Checking if {}{}'.format(parameter_name, pass_criteria), also_console=True)
        result = eval("{}{}".format(value_scf, pass_criteria))
        if result:
            return True
        raise AssertionError(
            "Parameter {} has incorrect value {}. Pass criteria: {}".format(
                parameter_name, scf_parameter, pass_criteria
            )
        )

    @log_method_name
    def get_converted_parameter_value_from_scf(self, parameter_name, dist_name, scfc_filepath):
        """
        :param parameter_name
        :param dist_name
        :param scfc_filepath
        """
        value = self.get_value_from_scf(parameter_name=parameter_name, dist_name=dist_name, scfc_filepath=scfc_filepath)
        return convert_parameter_to_integer(value)

