    @log_method_name
    def get_smod_position_on_given_fsmr4_enb(self, remote_host=None):
        smod_position_on_enb = self.execute_enb_command(
            cmd='cat /proc/device-tree/soc-identity/chassis-slot-number | xargs -0 echo', remote_host=remote_host
        )
        logger.info('Returned chassis-slot-number= ' + smod_position_on_enb)
        if smod_position_on_enb == '0':
            return 'LeftSide'
        elif smod_position_on_enb == '4':
            return 'RightSide'
        else:
            logger.info('Problem with collecting information about Rel4 ASIA position')

    def check_smod_position_and_set_value(self):
        release = self.get_enb_fsm_type()
        if release == '4':
            side = self.get_smod_position_on_given_fsmr4_enb()
            if side == 'RightSide':
                return '4'
            return '1'
        return '*'

