    @log_method_name
    def get_file_name(self, file_path, file_name_regex, remote_host=None):
        """
        :param file_path
        :param file_name_regex
        :param remote_host
        """
        found_file_path = self.execute_enb_command(
            cmd="find {path} -type f -name {file_name_regex}".format(path=file_path, file_name_regex=file_name_regex),
            remote_host=remote_host,
        )
        return found_file_path.split("/")[-1]

    def _prepare_extraction_argument(self, file_name, file_path):
        """
        :param file_name
        :param file_path
        """
        argument1 = file_path + file_name
        argument2 = " -C {path}".format(path=file_path)
        argument3 = file_path

        if "txz" in file_name:
            return argument1 + argument2
        elif "zip" in file_name:
            return "{arg1} {arg2}".format(arg1=argument3, arg2=argument1)
        return argument1

    @log_method_name
    def extract_file(self, file_name, file_path, sudo_execution=False, remote_host=None):
        """
        :param file_name
        :param file_path
        :param sudo_execution
        :param remote_host
        """
        argument = self._prepare_extraction_argument(file_name, file_path)

        if "txz" in file_name:
            command = "tar --overwrite -xvf {argument}".format(argument=argument)
        elif "xz" in file_name:
            command = "unxz {argument}".format(argument=argument)
        elif "zip" in file_name:
            command = "unzip -o -d {argument}".format(argument=argument)
        else:
            raise ExecutionFailed(
                message="Unknown compression type: {file}".format(file=file_name), continue_on_failure=False
            )

        if sudo_execution:
            command = "sudo {cmd}".format(cmd=command)

        self.execute_enb_command(cmd=command, remote_host=remote_host)

    @log_method_name
    def change_randd_flag_value(self, flag_name, value, file_name, file_path, remote_host=None):
        """
        :param flag_name
        :param value
        :param file_name
        :param file_path
        :param remote_host
        """
        self.execute_enb_command(
            cmd="sed -i -E 's/{flag_name}.*/{flag_name}={value}/g' {file_path}{file_name}".format(
                flag_name=flag_name, value=value, file_path=file_path, file_name=file_name
            ),
            remote_host=remote_host,
        )

