    @log_method_name
    def get_active_alarms(self, severity=None, remote_host=None):
        """
        Gets a dictionary with active alarms
        :param string remote_host: IP address of remote host
        :param string severity: Alarm severity (critical, major, minor or warning)
        :return: Returns list of active alarms
        """
        if remote_host is not None:
            with ta_admin_interface.remote_admin_interface(remote_host=remote_host) as remote_admin_client:
                active_alarms = remote_admin_client.get_active_alarms(severity=severity, remote_host=remote_host)
        else:
            with ta_admin_interface.admin_interface() as admin_client:
                active_alarms = admin_client.get_active_alarms(severity=severity)
        return active_alarms

    @log_method_name
    def alarm_single_verify(self, search_id, search_key, remote_host=None, severity=None):
        """
        Single check for alarm/fault
        :param string remote_host: IP address of remote host
        :param int search_id: Id of alarm or fault
        :param string search_key: Choose if you want to check: 'fault' or 'alarm'
        :param string severity: Alarm severity (critical, major, minor or warning)
        :return: Function returns bool: True or False
        """
        key_id = search_key + "Id"
        active_alarms = self.get_active_alarms(severity=severity, remote_host=remote_host)
        search_ids = [alarm[key_id] for alarm in active_alarms]
        does_exist = bool([found_id for found_id in search_ids if found_id == int(search_id)])
        return does_exist

