    def _verify_if_cell_fault_or_alarm_is_up(self, search_id, search_key, cell_id, severity=None, remote_host=None):
        active_faults_and_alarms = self.get_active_alarms(severity=severity, remote_host=remote_host)
        key_id = search_key + "Id"
        for alarm in active_faults_and_alarms:
            try:
                cell = alarm['impactedCellsListCliInfo'][0]['NR'][0]['cellId']
                if alarm[key_id] == int(search_id) and cell.split('-')[-1] == cell_id:
                    does_exist = True
                    break
            except Exception:
                pass
        else:
            does_exist = False
        ta5g_admin_operations().assert_equal(actual=does_exist, expected=True)

