    @log_method_name
    def verify_gnb_procedural_state(self, expected_status):
        """Possible status strings of ${expected_status}: configured; onAir"""
        gnb_procedural_state = self.get_gnb_procedural_state()
        return True if gnb_procedural_state == expected_status else False

    @log_method_name
    def wait_for_gnb_to_reach_configured_state(self, timeout=1200, time_step=10):
        """wait_for_gnb_to_reach_configured_state"""
        time_start = time.time()
        gnb_is_configured = self.verify_gnb_procedural_state(expected_status='Configured')
        while gnb_is_configured is False:
            gnb_is_configured = self.verify_gnb_procedural_state(expected_status='Configured')
            time_diff = float(time.time() - time_start)
            if time_diff > timeout:
                raise RuntimeError('wait_for_gnb_to_reach_configured_state: waited too long')
            time.sleep(time_step)

    def start_collecting_tti(self, component_list=["L2Ps"]):
        nr_cell_dns = self._get_all_cells_distnames()
        m_plane_ip_address = "10.0.1.2"

        self._start_tti_logs_collection(nr_cell_dns=nr_cell_dns,
                                        component_list=component_list,
                                        m_plane_ip_address=m_plane_ip_address)
        self.tti_collector_running = True

    def stop_and_collect_tti_without_conversion(self):
        if self.tti_collector_running:
            self.stop_tti_logs_collection(component_list=["L2Ps"])
            logs_path = BuiltIn().get_variable_value("${OUTPUT_DIR}")
            logs_path = os.path.join(logs_path, "snapshot.zip")
            self.get_bts_snapshot(output_filepath=logs_path)
            self.tti_collector_running = False

    def stop_and_collect_tti(self, events_file):
        if self.tti_collector_running:
            self.stop_tti_logs_collection(component_list=["L2Ps"])
            logs_path = BuiltIn().get_variable_value("${OUTPUT_DIR}")
            logs_path = os.path.join(logs_path, "snapshot.zip")
            self.get_bts_snapshot(output_filepath=logs_path)
            self.convert_captured_logs(events_file, file=logs_path)
            self.tti_collector_running = False

    def _get_all_cells_distnames(self, cell_type="nr", list_of_cells=None, connection=None):
        """
        Returns cell distnames for provided list of cells.
        :param cell_type: type of cell's that dist name should be obtained, `nr` at default.
        :type cell_type: str
        :param connection: object or alias of the admin connection set up earlier
        which is to be used to get information about objects
        :type connection: Union[AdminConnection,str]
        :return: list of all cell name distnames.
        :rtype: list
        """
        list_of_cells = list_of_cells if list_of_cells else [51, 52, 53, 57, 58, 60]

        with ta_admin_interface.admin_interface() as admin_client:
            cell_info = admin_client.get_cells_info(
                cell_type=cell_type, connection=connection
            )

        list_of_cell_distnames = [cell["id"]["internal"] for cell in cell_info if cell['physicalCellId'] in list_of_cells]
        return list_of_cell_distnames

    def _start_tti_logs_collection(
        self,
        nr_cell_dns,
        component_list,
        port=5678,
        m_plane_ip_address=None,
        timeout=60,
        connection=None,
        profile_filter_list=None,
    ):
        """
        Starts U-plane L2 Trace logs via AdminCli
        :param component_list: list of components that the trace logs will be collected from. One of L2Ps, L2HiRlc,
                               L2Lo, L2HiPDCP
        :type component_list: list of str
        :param nr_cell_dns: cell configuration dist_names to collect TTI trace logs from
        :type nr_cell_dns: list of str
        :param port: available destination port to collects log from, 5678 at default
        :type port: str or int
        :param m_plane_ip_address: BTS M-plane IP address
        :type m_plane_ip_address: str
        :param timeout: time in seconds to wait for positive procedure result
        :type timeout: str or int
        :param connection: AdminConnection object or string name alias
        :type connection: AdminConnection or str
        :param profile_filter_list: it is only allowed to be configured when upSw == 'L2Ps' and traceType ==
                                    'Component', if user do not configure l2PsProfileFilterList, ["Default"] will
                                    be used as default value, the profiles in l2PsProfileFilterList must be unique.
        :type profile_filter_list: list
        """
        logger.info(
            f"Starting TTI trace logs collection on components {component_list}"
        )

        tl = BuiltIn().get_variable_value("${tl}")
        connection_details = tl.gnbs[0].cu.oam_http_connection_details
        local_vm_ip = tl.test_pcs[0].default_ssh_connection_details.addr

        with ta_admin_interface.admin_interface() as admin_client:
            for component in component_list:
                admin_client.start_uplane_l2_trace(
                    source_ip=(
                        m_plane_ip_address
                        if m_plane_ip_address
                        else connection_details.addr
                    ),
                    dscp=10,
                    destination_ip=local_vm_ip,
                    destination_port=int(port),
                    nr_cell_dns=nr_cell_dns,
                    trace_type="Component",
                    up_sw=component,
                    timeout=int(timeout),
                    profile_filter_list=profile_filter_list,
                )

    def stop_tti_logs_collection(self, component_list, timeout=60, connection=None):
        """
        Stops BIP log collection on demand via AdminAPI and downloads it to test VM
        :param component_list: list of components that the trace logs will be collected from. One of L2Ps, L2HiRlc,
                               L2Lo, L2HiPDCP
        :type component_list: list of str
        :param timeout: time in seconds to wait for positive procedure result
        :type timeout: str or int
        :param connection: AdminConnection object or string name alias
        :type connection: AdminConnection or str
        """

        exception = None
        for component in component_list:
            try:
                with ta_admin_interface.admin_interface() as admin_client:
                    admin_client.stop_uplane_l2_trace(
                        trace_type="Component",
                        up_sw=component,
                        timeout=int(timeout),
                    )

            except Exception as e:
                exception = e

        if exception is not None:
            raise exception

    def convert_captured_logs(self, events_file, file=None):
        """
        Unpacks .bin.xz file from downloaded snapshot and extracts L2Ps events
        :param file: full path to downloaded snapshot file. Default snapshot location if not specified ($logs_path)
        :type file: str
        :param filtered_events: single report is very big, so it is mandatory to add .txt file with listed
                                event names that will be excluded from reporting.

        :return: list of full paths to extracted L2Ps events snapshot bin file and decoded to jso
        :rtype: list of str
        """
        filtered_events = events_file

        bin_file_paths = self._get_bin_files(file=file)
        decoder_path = self._download_tti_trace_decoder_tool(
            path=os.path.dirname(bin_file_paths[0])
        )

        return self._decode_tti_trace(
            event_files=bin_file_paths,
            decoder_path=decoder_path,
            filtered_events=filtered_events,
        )

    def _get_bin_files(self, file=None):
        """
        Gets L2TtiTrace_EventsSnapshot.bin.xz file from snapshot, unpacks it to provided output directory
        :param file: full path to snapshot file
        :type file: str
        :return: list of full paths to obtained TTI binaries files
        :rtype: list of str
        :raises NoL2PsBinFound: when bin file is not found inside a snapshot
        """
        tti_trace_name = "L2TtiTrace_EventsSnapshot.bin.xz"
        current_logs_path = BuiltIn().get_variable_value("${OUTPUT_DIR}")
        file = file if file else os.path.join(current_logs_path, "snapshot.zip")
        file_dir, file_name = os.path.split(file)
        alias = "tti_traces"
        tti_trace_path = os.path.join(file_dir, alias)
        os.makedirs(tti_trace_path, exist_ok=True)

        z = zipfile.ZipFile(file)

        binaries_paths = []

        for file in z.namelist():
            content = io.BytesIO(z.read(file))
            try:
                zip_file = zipfile.ZipFile(content)

                sub_zip_content = zip_file.namelist()
                snapshot_files = [
                    file for file in sub_zip_content if re.search(tti_trace_name, file)
                ]

                if snapshot_files:

                    for snapshot_file in snapshot_files:
                        zip_file.extract(member=snapshot_file, path=tti_trace_path)

                        binary_path = f'{tti_trace_path}/{snapshot_file.strip(".xz")}'

                        with lzma.open(
                            f"{tti_trace_path}/{snapshot_file}"
                        ) as bin_xz_file, open(binary_path, "wb") as bin_file:
                            file_content = bin_xz_file.read()
                            bin_file.write(file_content)

                            binaries_paths.append(binary_path)

            except zipfile.BadZipfile:
                continue

        if not binaries_paths:
            raise IndexError(
                f"Could not find EventSnapshot files found inside {file}!"
            )

        return binaries_paths

    def _download_tti_trace_decoder_tool(self, path):
        """
        Downloads TTI Trace decoding tool from artifactory, exact for particular detected active software version
        on SBTS as tools differ between airscale software versions.
        """

        tti_decoder_tool_name = "tti-dec_qemux86-64-static.txz"
        sw_version = None

        tti_trace_path = os.path.join(path, "tti_trace_decoder")
        os.makedirs(tti_trace_path, exist_ok=True)

        try:
            sw_version = self.get_software_info()

            branch = sw_version[0].split("_")[0]

            tti_dec_link = (
                f"https://artifactory-espoo2.int.net.nokia.com/artifactory/"
                f"mn-cosi-sran-central-public-local/build/"
                f"{branch}/{sw_version[0]}/{sw_version[0]}_{tti_decoder_tool_name}"
            )

            get_file_command = f"cd {tti_trace_path} && wget -r -np -nd -e robots=off {tti_dec_link}"

            self.execute_command_on_test_vm(command=get_file_command)

            tti_dec_tar_path = os.path.join(
                tti_trace_path, f"{sw_version[0]}_{tti_decoder_tool_name}"
            )

            tti_dec_tar = tarfile.open(tti_dec_tar_path, mode="r:xz")

            tti_dec_tar.extractall(path=tti_trace_path)

            decoder_path = f"{tti_trace_path}/tti-dec-bin"

            return decoder_path

        finally:
            if sw_version:
                tti_dec_tar_path = os.path.join(
                    tti_trace_path, f"{sw_version[0]}_{tti_decoder_tool_name}"
                )
                self.execute_command_on_test_vm(command=f"rm -rf {tti_dec_tar_path}")

    def _decode_tti_trace(self, event_files, decoder_path, filtered_events, cell_type="TDD"):
        """
        Decodes TTI trace bin file into json by dedicated tti-dec-bin tool downloaded by
        `download_tti_trace_decoder_tool` so it is recommended to use the method mentioned before as first.
        Output json will be provided and saved under `l2ps_bin_path` parent directory.
        :param file: full path to L2PS bin file
        :type file: str
        :param decoder_path: path to extracted tti decoder directory.
        :type decoder_path: str
        :param filtered_events: single report is very big, so it is mandatory to add .txt file with listed
                                event names that will be excluded from reporting.
        :type filtered_events: str
        :returns list of full paths to created json output.
        :rtype: list of str
        """
        tti_decoder_name = "TtiTraceDecoder.py"
        decoded_files = []

        event_files = [file for file in event_files if cell_type in file]

        for event_file in event_files:
            file_dir, file_name = os.path.split(event_file)

            decode_command = (
                f"python {os.path.join(decoder_path, tti_decoder_name)} {event_file} json -e {filtered_events} "
                f"-o {event_file.strip('.bin').split('/')[-1]}"
            )
            output = self.execute_command_on_test_vm(
                command=decode_command, ignore_error=True, timeout=300
            )

            with open(f"{file_dir}/output.log", "w") as log_file:
                log_file.write(output)

            cleaned_output = [line for line in output.split("\n") if line]

            if "EventDecoder fail" in cleaned_output[-1]:
                raise Exception(f"Could not decode {event_file} due to decoder error - please check output.log")
            else:
                dst_decoded_path = os.path.join(
                    file_dir, f"{event_file.strip('.bin')}.json"
                )
                decoded_files.append(dst_decoded_path)

        return decoded_files

    def get_software_info(self, translate=True, timeout=60, connection=None):
        """
        Gets software version from active, passive and planned version (if exists) from airscale via admin client.
        :param translate: translation to SBTS00 of current's master branch. Defaults to True
        :type translate: bool
        :param timeout: operation timeout
        :type timeout: str or int
        :param connection: AdminConnection object or string name alias
        :type connection: AdminConnection or str
        :return: active, passive, planned software
        :rtype: tuple[str, str, str]
        """
        try:
            with ta_admin_interface.admin_interface() as admin_client:
                sw_info = admin_client.get_software_info(
                    connection=connection, timeout=timeout
                )
        except Exception as e:
            logger.warn(e)
            return "failed", "failed", "failed"

        sw_builds = {}
        for build_type in [
            "Active SW version",
            "Passive SW version",
            "Planned SW version",
        ]:
            sw_build = sw_info.get(build_type)

            if sw_build is None:
                sw_build = ""

            elif translate:
                release = sw_build.split("_", 1)[0]
                sw_build = (
                    sw_build.replace(release, "SBTS00")
                    if "_ENB_9999" in sw_build
                    else sw_build
                )
            sw_builds[build_type.split(" ")[0].lower()] = sw_build

        return sw_builds["active"], sw_builds["passive"], sw_builds["planned"]

    def execute_command_on_test_vm(
        self, command, ignore_error=False, timeout=45, use_popen_instead_of_run=False
    ):
        """
        Executes command on test VM

        :param command: command that will be executed
        :type command: str or list
        :param ignore_error: determines whether the error should be printed as warning or not
        :type ignore_error: bool
        :param timeout: timeout for command execution
        :type timeout: int
        :param use_popen_instead_of_run: determines whether it should use subprocess.Popen instead of subprocess.Run -
        used to run command in background. Note that command has to be of type 'list' in order to use Popen.
        :type use_popen_instead_of_run: bool
        :return: command's output
        :rtype: str
        """
        if use_popen_instead_of_run:
            return subprocess.Popen(
                command.split(" "), stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL
            )

        try:
            output = subprocess.run(
                command, shell=True, capture_output=True, check=True, timeout=timeout
            )

        except subprocess.CalledProcessError as e:
            if ignore_error:
                logger.warn(
                    f"Error during command execution: {command} \n"
                    f"Error output: {e.stderr.decode().strip()}\n"
                    f"Error code: {e.returncode}"
                )
                return e.stdout.decode(errors="replace").strip()
            else:
                raise

        else:
            return output.stdout.decode(errors="replace").strip()

    @log_method_name
    def configure_l1_iq_data(self, module_dn=None, capture_on_event=False, dl_nr_cell=None, dl_nr_subcell=None,
                             ul_nr_cell=None, ul_nr_subcell=None, dl_lte_subcell_list=None, ul_lte_subcell_list=None,
                             capture_on_event_bb_ru=None, capture_ru_list=None, buffer_cycle=None, capture_frame_offset=None, timeout=120,
                             detailed_output=False, capture_mode=None):
        """it is necessary to set dl_nr_cell and dl_nr_subcell or ul_nr_cell andul_nr_subcell"""

        if not module_dn:
            module_dn = self.get_bbmod_runtime_dn()
            logger.console(module_dn)
        if dl_nr_subcell:
            dl_nr_subcell = [{"nrcellDN": "MRBTS-1/NRBTS-1/NRCELL-{}".format(dl_nr_cell), "subcellId": int(dl_nr_subcell)}]
            logger.console(dl_nr_subcell)
        if ul_nr_subcell:
            ul_nr_subcell = [{"nrcellDN": "MRBTS-1/NRBTS-1/NRCELL-{}".format(ul_nr_cell), "subcellId": int(ul_nr_subcell)}]
            logger.console(ul_nr_subcell)

        with ta_admin_interface.admin_interface() as admin_client:
            admin_client.configure_uplane_l1_iq_data(
                module_dn=module_dn,
                capture_on_event=capture_on_event,
                dl_nr_subcell_list=dl_nr_subcell,
                ul_nr_subcell_list=ul_nr_subcell,
                dl_lte_subcell_list=dl_lte_subcell_list,
                ul_lte_subcell_list=ul_lte_subcell_list,
                capture_on_event_bb_ru=capture_on_event_bb_ru,
                capture_ru_list=capture_ru_list,
                buffer_cycle=buffer_cycle,
                capture_frame_offset=capture_frame_offset,
                timeout=timeout,
                detailed_output=detailed_output,
                capture_mode=capture_mode)

    @log_method_name
    def collect_l1_iq_data(self, log_dirpath=None, module_dn=None, sfn=65535, slot=0,
                           capture_mode='ScheduleSynchronousStopOfOngoingContinuousCapture', timeout=120,
                           detailed_output=False):
        if log_dirpath is None:
            log_dirpath = get_robot_output_dir()
