    def get_ip_vcu_master(self):
        tl = BuiltIn().get_variable_value("${tl}")
        return tl.cloud_hostings[0].master_node.ssh_connection_details.addr

    def get_namespace_for_vcu(self):
        tl = BuiltIn().get_variable_value("${tl}")
        return tl.cloud_hostings[0].namespace

    @log_method_name
    def deploy_multi_cpcell(self):
        """
        Deploy multi cpcell
        :return:
        """
        logger.console("Starting deploy of multiple CPCL instances in vCU")
        with ta5g_admin_operations().connect_to_vcu_aic() as vcu_connection:
            vcu_version = vcu_connection.get_active_software_version()
        soft = vcu_version.split("_")[-1]
        namespace = self.get_namespace_for_vcu()
        hostname = socket.gethostname().replace("-", "_").upper()
        host = self.get_ip_vcu_master()
        sw_dir = "{local_hostname}/vCUCNF00_{soft}/0".format(local_hostname=hostname, soft=soft)
        with ta_admin_common_operations.create_shell_session_vcu(host) as connection:
            connection.send_shell_command("helm uninstall vcucnf -n {} --debug"
                                          .format(namespace))

            connection.send_shell_command("sed -i 's/cpclInstanceCount: 1/cpclInstanceCount: 2/g' \
                                          /var/home/core/{}/HelmChart/cnf/aic-vcu/tl.yaml"
                                          .format(sw_dir))
            connection.send_shell_command("sed -i 's/cpclInstanceCount: 1/cpclInstanceCount: 2/g' \
                                          /var/home/core/{}/HelmChart/cnf/aic-vcu/values-override.yaml"
                                          .format(sw_dir))
            connection.send_shell_command("sed -i 's/cnfLayout: basic/cnfLayout: redundant/g' \
                                          /var/home/core/{}/HelmChart/cnf/aic-vcu/tl.yaml"
                                          .format(sw_dir))
            connection.send_shell_command("sed -i 's/cnfLayout: \"basic\"/cnfLayout: \"redundant\"/g' \
                                          /var/home/core/{}/HelmChart/cnf/aic-vcu/values-override.yaml"
                                          .format(sw_dir))
            connection.send_shell_command("sed -i 's/featureCB009789H: false/featureCB009789H: true/g' \
                                          /var/home/core/{}/HelmChart/cnf/aic-vcu/values.yaml"
                                          .format(sw_dir))
            connection.send_shell_command("sed -i 's/rangeEnd: 172.16.2.101/rangeEnd: 172.16.2.102/g' \
                                          /var/home/core/{}/HelmChart/cnf/aic-vcu/vcu-cnf-common.yaml"
                                          .format(sw_dir))
            connection.send_shell_command("sed -i 's/rangeEnd: 10.0.1.210/rangeEnd: 10.0.1.211/g' \
                                          /var/home/core/{}/HelmChart/cnf/aic-vcu/vcu-cnf-common.yaml"
                                          .format(sw_dir))
            connection.send_shell_command("sed -i 's/rangeEnd: 10.0.11.210/rangeEnd: 10.0.11.211/g' \
                                          /var/home/core/{}/HelmChart/cnf/aic-vcu/vcu-cnf-common.yaml"
                                          .format(sw_dir))
            connection.send_shell_command("sed -i 's/rangeEnd: 10.0.12.210/rangeEnd: 10.0.12.211/g' \
                                          /var/home/core/{}/HelmChart/cnf/aic-vcu/vcu-cnf-common.yaml"
                                          .format(sw_dir))

            shin_install, shout_install, sherr_install = connection.send_shell_command("cd /var/home/core/{sw_dir}/HelmChart/cnf/aic-vcu/ && \
                                                                                       helm install vcucnf . -f values-override.yaml -f tl.yaml \
                                                                                       -f vcu-cnf-common.yaml -n {namespace} --timeout 25m --debug"
                                                                                       .format(sw_dir=sw_dir, namespace=namespace))

            shin, shout, sherr = connection.send_shell_command("helm list -n {} ".format(namespace))
            for element in shout:
                if 'vcucnf' in element and 'deployed' in element:
                    break
            else:
                raise Exception('vcucnf not created with errors: {}'.format(shout_install))


